-- PostgreSQL 17+ / Neon. Ejecutar una sola vez dentro de una base vacía.
-- Crea el esquema y los datos de ejemplo; no elimina tablas ni datos existentes.
-- Los identificadores con mayúsculas se escriben siempre entre comillas dobles.
BEGIN;

CREATE TABLE public."Mesas" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_Mesas" PRIMARY KEY,
    "Numero" integer NOT NULL,
    "Capacidad" integer NOT NULL,
    "Ubicacion" varchar(80) NOT NULL,
    CONSTRAINT "UQ_Mesas_Numero" UNIQUE ("Numero"),
    CONSTRAINT "CK_Mesas_Numero" CHECK ("Numero" BETWEEN 1 AND 200),
    CONSTRAINT "CK_Mesas_Capacidad" CHECK ("Capacidad" BETWEEN 1 AND 20),
    CONSTRAINT "CK_Mesas_Ubicacion" CHECK (length(trim("Ubicacion")) > 0)
);

CREATE TABLE public."Reservas" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_Reservas" PRIMARY KEY,
    "NombreCliente" varchar(100) NOT NULL,
    "Telefono" varchar(20) NOT NULL,
    -- Hora local del restaurante en Lima: enviar ISO 8601 sin Z ni offset.
    "FechaHora" timestamp(0) without time zone NOT NULL,
    "CantidadPersonas" integer NOT NULL,
    "Observaciones" varchar(300),
    "MesaId" integer NOT NULL,
    CONSTRAINT "FK_Reservas_Mesas" FOREIGN KEY ("MesaId")
        REFERENCES public."Mesas"("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_Reservas_Personas" CHECK ("CantidadPersonas" BETWEEN 1 AND 20),
    CONSTRAINT "CK_Reservas_Cliente" CHECK (length(trim("NombreCliente")) > 0),
    CONSTRAINT "CK_Reservas_Telefono" CHECK (length(trim("Telefono")) > 0)
);

CREATE INDEX "IX_Reservas_MesaId" ON public."Reservas"("MesaId");
CREATE INDEX "IX_Reservas_FechaHora" ON public."Reservas"("FechaHora");

INSERT INTO public."Mesas" ("Numero", "Capacidad", "Ubicacion") VALUES
    (1, 4, 'Salón principal'),
    (2, 6, 'Terraza'),
    (3, 2, 'Ventana'),
    (4, 8, 'Salón familiar');

INSERT INTO public."Reservas"
    ("NombreCliente", "Telefono", "FechaHora", "CantidadPersonas", "Observaciones", "MesaId")
VALUES
    ('Ana Torres', '999111222', '2026-12-10T13:00:00', 4, 'Almuerzo familiar', 1),
    ('Luis Ramos', '999333444', '2026-12-10T20:00:00', 5, NULL, 2),
    ('María López', '999555666', '2026-12-11T19:30:00', 2, 'Junto a la ventana', 3);

COMMIT;
